// KB Files: club staff teach the WhatsApp bot from a picture, a PDF or a text file (Bot Knowledge in the admin panel).
//   extract  the AI reads the file and lists the facts it found. NOTHING is learned yet: staff review the list first.
//   save     the facts staff approved (and may have corrected) become rows of kb_chunks, which the bot searches.
//   remove   the bot forgets everything it learned from one file.
// Rules that hold whatever the file or the caller says:
//   - only an owner or manager of the club, signed in, can use it;
//   - a fact with a price or amount, a phone / account / identity number, an email or UPI ID, a web link or member
//     data is never saved: those come only from Settings. The check runs here again on save, not only in the page;
//   - the file itself is not stored; at most DAY_LIMIT files per club per day, and one AI call to read a file plus
//     one to index its facts, so the AI key's quota cannot be drained from this screen.
const H=this.helpers;
try{
const SUPA='__SUPABASE_URL__',SR='__SUPABASE_SERVICE_KEY__',ANON='__SUPABASE_ANON_KEY__',GK='__GEMINI_KEY__';
const sH={apikey:SR,Authorization:'Bearer '+SR,'Content-Type':'application/json'};
const b=($input.first().json.body)||{};
const out=(o)=>[{json:o}];
const parse=(x)=>{ if(typeof x==='string'){ try{ return JSON.parse(x); }catch(e){ return null; } } return x; };
const req=async(method,path,body,prefer)=>{ const r=await H.httpRequest({method,url:SUPA+'/rest/v1/'+path,headers:prefer?{...sH,Prefer:prefer}:sH,body:body===undefined?undefined:JSON.stringify(body),returnFullResponse:true,ignoreHttpStatusErrors:true,timeout:20000}); return {status:r.statusCode,body:parse(r.body)}; };
const DAY_LIMIT=10, MAX_BYTES=4*1024*1024, MAX_TEXT=60000, MAX_FACTS=40, FACT_MAX=400;
/* tried in order; a model Google no longer serves to this key (404) is skipped; a quota answer (429) stops at once */
const AI_MODELS=['gemini-2.5-flash','gemini-3.6-flash','gemini-3.8-flash'];
const FILE_TYPES=['image/jpeg','image/png','image/webp','application/pdf'];
const oneLine=(v,n)=>String(v==null?'':v).replace(/\s+/g,' ').trim().slice(0,n||200);
const isUuid=(v)=>/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(String(v||''));

/* why a fact may not be learned from a file ('' = it may) */
function sensitiveWhy(t){
  const s=String(t||'');
  if(/https?:\/\/|\bwww\.[a-z0-9-]+\.[a-z]/i.test(s)) return 'link';
  if(/[A-Z0-9._%+-]+@[A-Z0-9-]+(\.[A-Z0-9-]+)*/i.test(s)) return 'contact';
  if(/\b(ifsc|a\/c|acc(oun)?t\.?\s*(no|number|#)|aadhaa?r|pan\s*(no|number|card)|passport|password|passcode|otp|cvv|card\s*(no|number)|upi|bank\s+(account|details))\b/i.test(s)) return 'identity';
  if(/(?:\d[\s().-]?){8,}/.test(s)) return 'number';
  if(/₹|\$\s?\d|\b(rs|inr)\b\.?\s*\d|\d[\d,.]*\s*(\/-|rs\b|inr\b|rupees?\b|lakhs?\b|crores?\b)|\brupees?\b/i.test(s)) return 'money';
  if(/\d/.test(s)&&/\b(fees?|prices?|pricing|priced|charges?|charged|costs?|tariff|rates?|discount|penalty|fine|gst|tax|deposit|refund|amount|payable|dues?)\b/i.test(s)) return 'money';
  if(/\b(member(ship)?\s*(no|number|id|code)\b\.?\s*[:#-]?\s*[A-Z0-9-]*\d|date\s+of\s+birth|d\.?o\.?b\b)/i.test(s)||/\b[A-Z]{2,5}[- ]?\d{3,}\b/.test(s)) return 'member';
  return '';
}

/* the club, and the signed-in owner or manager */
const slug=oneLine(b.tenant||'shakti',60);
const tr=await req('GET','tenants?slug=eq.'+encodeURIComponent(slug)+'&select=id,name');
const t=Array.isArray(tr.body)?tr.body[0]:null; if(!t) return out({ok:false,error:'Club not found.'});
const TID=t.id;
if(!b.user_token) return out({ok:false,error:'Not authorized: please sign in again.'});
let u=null;
try{ const r=await H.httpRequest({method:'GET',url:SUPA+'/auth/v1/user',headers:{apikey:ANON,Authorization:'Bearer '+b.user_token,Accept:'application/json'},returnFullResponse:true,ignoreHttpStatusErrors:true,timeout:15000});
  if(r.statusCode>=400) return out({ok:false,error:'Your session has expired. Refresh the page and sign in again.'}); u=parse(r.body); }
catch(e){ return out({ok:false,error:'The sign-in could not be checked. Try again.'}); }
if(!u||!u.id) return out({ok:false,error:'Not authorized: invalid sign-in.'});
const ar=await req('GET','app_admins?select=role,email&user_id=eq.'+u.id+'&tenant_id=eq.'+TID);
const adm=Array.isArray(ar.body)?ar.body[0]:null;
if(!adm) return out({ok:false,error:'This sign-in is not on staff for the club.'});
const role=String(adm.role||'').toLowerCase();
if(!['owner','manager'].includes(role)) return out({ok:false,error:'Only an owner or manager can teach the bot from files.'});
const who=adm.email||u.email||'staff';

const dayStart=new Date(Date.parse(new Date(Date.now()+330*60000).toISOString().slice(0,10)+'T00:00:00+05:30')).toISOString();
const usedToday=async()=>{ const r=await req('GET','kb_files?tenant_id=eq.'+TID+'&created_at=gte.'+encodeURIComponent(dayStart)+'&select=id'); return Array.isArray(r.body)?r.body.length:null; };
const cleanFacts=(list)=>{ const seen=new Set(), res=[];
  for(const f of (Array.isArray(list)?list:[])){ const fact=oneLine(f&&f.fact,FACT_MAX), topic=oneLine(f&&f.topic,40); const k=fact.toLowerCase();
    if(fact.length<8||seen.has(k)) continue; seen.add(k); res.push({topic,fact,why:sensitiveWhy(topic+' '+fact)}); if(res.length>=MAX_FACTS) break; }
  return res; };
const QUOTA_MSG='The AI has reached its usage limit for now, so the file was not read. Nothing was changed. Try again later (the limit resets daily); the bot keeps answering from what it already knows.';

// ---------------- extract ----------------
if(b.action==='extract'){
  const name=oneLine(b.name,120)||'file', mime=oneLine(b.mime,80).toLowerCase();
  const gapQ=isUuid(b.gap_id)?oneLine(b.question,300):'';
  const hint=oneLine(b.hint,500);   /* what staff asked the AI to take from this file */   /* started from a member's open question: read the file for that question only */
  const text=typeof b.text==='string'?b.text:'';
  const data=String(b.file_base64||'').replace(/\s+/g,'');
  let size=0;
  if(text){ if(text.length>MAX_TEXT) return out({ok:false,error:'This file has too much text ('+text.length.toLocaleString('en-IN')+' characters; the limit is '+MAX_TEXT.toLocaleString('en-IN')+'). Split it into smaller files.'}); if(text.trim().length<20) return out({ok:false,error:'This file has almost no text to learn from.'}); size=text.length; }
  else{
    if(!FILE_TYPES.includes(mime)) return out({ok:false,error:'This kind of file cannot be read. Use a JPG, PNG or WEBP picture, a PDF, or a text / CSV / Excel file.'});
    if(!data||!/^[A-Za-z0-9+/]+=*$/.test(data)) return out({ok:false,error:'No file was received.'});
    size=Math.floor(data.length*3/4)-(data.endsWith('==')?2:data.endsWith('=')?1:0);
    if(size>MAX_BYTES) return out({ok:false,error:'The file must be under 4 MB.'});
  }
  const used=await usedToday();
  if(used===null) return out({ok:false,error:'File training is not set up yet: run sql/kb_files.sql in the Supabase SQL editor.'});
  if(used>=DAY_LIMIT) return out({ok:false,limit:true,used_today:used,day_limit:DAY_LIMIT,error:'The club has used all '+DAY_LIMIT+' file uploads for today. This limit protects the AI quota the bot needs to answer members. Try again tomorrow.'});
  const ins=await req('POST','kb_files',{tenant_id:TID,name,mime:text?'text/plain':mime,size_bytes:size,status:'reading',uploaded_by:who},'return=representation');
  const row=Array.isArray(ins.body)?ins.body[0]:null;
  if(ins.status>=300||!row) return out({ok:false,error:'The upload could not be recorded, so the file was not read.'});
  const fail=async(msg,extra)=>{ await req('PATCH','kb_files?id=eq.'+row.id,{status:'failed',summary:oneLine(msg,200)},'return=minimal'); return out(Object.assign({ok:false,error:msg,file_id:row.id,used_today:used+1,day_limit:DAY_LIMIT},extra||{})); };
  const instruction='KB-FILE-EXTRACT. You are reading a document that staff of "'+t.name+'" uploaded so that the club\'s WhatsApp assistant can answer members from it. '
    +'List every fact in it that a member might ask about: rules, timings, schedules, facilities, procedures, dates, eligibility, what is allowed or not allowed. '
    +(hint?('The staff member who uploaded it wrote this note about the file: "'+hint+'". Follow any instruction in it when choosing which facts to list, and use it as context (what the document is, the period it covers, who it is for). You may also list a fact that the note itself states. Never add anything that is in neither the document nor the note. '):'')
    +(gapQ?('A member asked: "'+gapQ+'". List ONLY the facts in the document that help answer this question (at most 8). If the document does not answer it, return an empty facts list. '):'')
    +'Write each fact as ONE short, complete sentence in plain English that makes sense on its own (name the subject; never "it" or "the above"). Translate if the document is in another language. '
    +'Copy what the document says: do NOT guess, add, or fill in anything that is not written there. If something is unreadable, leave it out. At most '+MAX_FACTS+' facts, each under 300 characters. '
    +'Reply with JSON only, in exactly this shape: {"summary":"one line saying what this document is","facts":[{"topic":"two or three words","fact":"the sentence"}]}';
  const parts=text?[{text:instruction},{text:'DOCUMENT ('+name+'):\n'+text}]:[{text:instruction},{inline_data:{mime_type:mime,data}}];
  const bodyStr=JSON.stringify({contents:[{parts}],generationConfig:{temperature:0.1,maxOutputTokens:4096,responseMimeType:'application/json',thinkingConfig:{thinkingBudget:0}}});
  let found=null, lastErr='';
  for(const model of AI_MODELS){
    let g=null; try{ g=await H.httpRequest({method:'POST',url:'https://generativelanguage.googleapis.com/v1beta/models/'+model+':generateContent?key='+GK,headers:{'Content-Type':'application/json'},body:bodyStr,returnFullResponse:true,ignoreHttpStatusErrors:true,timeout:60000}); }catch(e){ lastErr='the AI did not answer in time'; continue; }
    const gb=parse(g.body)||{};
    if(g.statusCode===429) return await fail(QUOTA_MSG,{quota:true});
    if(g.statusCode===404){ lastErr='model not available'; continue; }
    if(g.statusCode>=400){ lastErr=oneLine((gb.error&&gb.error.message)||('HTTP '+g.statusCode),120); break; }
    const cand=(gb.candidates||[])[0]||{}; const txt=((cand.content||{}).parts||[]).filter(p=>p&&!p.thought&&typeof p.text==='string').map(p=>p.text).join('').trim();
    const j=parse(txt.replace(/^```(?:json)?\s*/i,'').replace(/```\s*$/,''));
    if(j&&Array.isArray(j.facts)){ found=j; break; }
    lastErr='the AI did not return a readable list'; break;
  }
  if(!found) return await fail('The AI could not read this file ('+(lastErr||'no answer')+'). Nothing was learned. Try a clearer picture or a smaller file.');
  const facts=cleanFacts(found.facts);
  const blocked=facts.filter(f=>f.why).length;
  const summary=oneLine(found.summary,200);
  await req('PATCH','kb_files?id=eq.'+row.id,{status:'review',summary,facts_found:facts.length,facts_blocked:blocked},'return=minimal');
  return out({ok:true,file_id:row.id,name,summary,facts:facts.map(f=>({topic:f.topic,fact:f.fact,blocked:!!f.why,why:f.why})),used_today:used+1,day_limit:DAY_LIMIT});
}

// ---------------- note: facts typed by staff, one per line (no file, no reading by the AI) ----------------
if(b.action==='note'){
  const raw=String(b.text||''); if(raw.length>4000) return out({ok:false,error:'The note is too long ('+raw.length.toLocaleString('en-IN')+' characters; the limit is 4,000). Split it into two notes.'});
  const lines=raw.split(/\r?\n/).map(l=>oneLine(l.replace(/^\s*(?:[-*\u2022]|\d+[.)])\s+/,''),FACT_MAX)).filter(l=>l.length>=8).slice(0,MAX_FACTS);
  if(!lines.length) return out({ok:false,error:'Type what the bot should know, one fact per line (at least a few words each).'});
  const used=await usedToday();
  if(used===null) return out({ok:false,error:'File training is not set up yet: run sql/kb_files.sql in the Supabase SQL editor.'});
  if(used>=DAY_LIMIT) return out({ok:false,limit:true,used_today:used,day_limit:DAY_LIMIT,error:'The club has used all '+DAY_LIMIT+' uploads and notes for today. This limit protects the AI quota the bot needs to answer members. Try again tomorrow.'});
  if(!cleanFacts(lines.map(l=>({topic:'',fact:l}))).some(x=>!x.why)) return out({ok:false,skipped:cleanFacts(lines.map(l=>({topic:'',fact:l}))).map(x=>({fact:x.fact,why:x.why})),error:'None of these lines can be learned from a note: they contain prices, numbers, payment or member details. Those come only from Settings.'});
  const title='Typed note: '+oneLine(lines[0],60);
  const ins=await req('POST','kb_files',{tenant_id:TID,name:title,mime:'text/note',size_bytes:raw.length,status:'review',summary:'Typed by staff',facts_found:lines.length,uploaded_by:who},'return=representation');
  const nrow=Array.isArray(ins.body)?ins.body[0]:null;
  if(ins.status>=300||!nrow) return out({ok:false,error:'The note could not be recorded, so nothing was saved.'});
  /* from here it is an ordinary save of approved lines */
  b.action='save'; b.file_id=nrow.id; b.facts=lines.map(l=>({topic:'',fact:l})); b.gap_id=null;
}

// ---------------- save ----------------
if(b.action==='save'){
  if(!isUuid(b.file_id)) return out({ok:false,error:'Which file? Upload it again.'});
  const fr=await req('GET','kb_files?id=eq.'+b.file_id+'&tenant_id=eq.'+TID+'&select=id,name,status');
  const row=Array.isArray(fr.body)?fr.body[0]:null;
  if(!row||row.status==='removed') return out({ok:false,error:'This file is no longer in the list. Upload it again.'});
  const all=cleanFacts(b.facts);
  const good=all.filter(f=>!f.why), skipped=all.filter(f=>f.why).map(f=>({fact:f.fact,why:f.why}));
  if(!good.length) return out({ok:false,skipped,error:skipped.length?'None of these lines can be learned from a file: they contain prices, numbers, payment or member details. Those come only from Settings.':'Tick at least one line for the bot to learn.'});
  const gapId=isUuid(b.gap_id)?b.gap_id:null;
  const rows=good.map(f=>({tenant_id:TID,file_id:row.id,source:'file',content:'From an uploaded file ("'+row.name+'")'+(f.topic?(', '+f.topic):'')+': '+f.fact,meta:{file_id:row.id,file_name:row.name,topic:f.topic,taught_by:who,gap_id:gapId}}));
  let e=null; try{ e=await H.httpRequest({method:'POST',url:'https://generativelanguage.googleapis.com/v1beta/models/gemini-embedding-001:batchEmbedContents?key='+GK,headers:{'Content-Type':'application/json'},body:JSON.stringify({requests:rows.map(r=>({model:'models/gemini-embedding-001',content:{parts:[{text:r.content}]},taskType:'RETRIEVAL_DOCUMENT',outputDimensionality:768}))}),returnFullResponse:true,ignoreHttpStatusErrors:true,timeout:60000}); }catch(err){ return out({ok:false,error:'The AI did not answer in time, so nothing was saved. Try again.'}); }
  if(e.statusCode===429) return out({ok:false,quota:true,error:QUOTA_MSG.replace('the file was not read','nothing was saved')});
  const eb=parse(e.body)||{}; const embs=Array.isArray(eb.embeddings)?eb.embeddings.map(x=>x&&x.values):[];
  if(e.statusCode>=400||embs.length!==rows.length||embs.some(v=>!Array.isArray(v)||v.length!==768)) return out({ok:false,error:'The AI could not index these lines ('+oneLine((eb.error&&eb.error.message)||('HTTP '+e.statusCode),100)+'). Nothing was saved.'});
  rows.forEach((r,i)=>{ r.embedding='['+embs[i].join(',')+']'; });
  await req('DELETE','kb_chunks?file_id=eq.'+row.id+'&tenant_id=eq.'+TID,undefined,'return=minimal');   /* teaching a file again replaces what it taught before */
  const ins=await req('POST','kb_chunks',rows,'return=minimal');
  if(ins.status>=300) return out({ok:false,error:'The lines could not be saved ('+oneLine((ins.body&&ins.body.message)||('HTTP '+ins.status),100)+').'});
  await req('PATCH','kb_files?id=eq.'+row.id,{status:'learned',facts_saved:rows.length,facts_blocked:skipped.length,learned_at:new Date().toISOString()},'return=minimal');
  let gapDone=false;
  if(gapId){ const gr=await req('GET','kb_gaps?id=eq.'+gapId+'&tenant_id=eq.'+TID+'&select=id');
    if(Array.isArray(gr.body)&&gr.body.length){ const up=await req('PATCH','kb_gaps?id=eq.'+gapId+'&tenant_id=eq.'+TID,{status:'answered',answer:oneLine('Taught from the file "'+row.name+'" ('+rows.length+' line'+(rows.length!==1?'s':'')+')',300),resolved_at:new Date().toISOString()},'return=minimal'); gapDone=up.status<300; } }
  return out({ok:true,saved:rows.length,skipped,by:who,gap_answered:gapDone});
}

// ---------------- remove ----------------
if(b.action==='remove'){
  if(!isUuid(b.file_id)) return out({ok:false,error:'Which file?'});
  const fr=await req('GET','kb_files?id=eq.'+b.file_id+'&tenant_id=eq.'+TID+'&select=id,name');
  const row=Array.isArray(fr.body)?fr.body[0]:null; if(!row) return out({ok:false,error:'This file is not in the list.'});
  const del=await req('DELETE','kb_chunks?file_id=eq.'+row.id+'&tenant_id=eq.'+TID,undefined,'return=minimal');
  if(del.status>=300) return out({ok:false,error:'The bot could not forget this file. Try again.'});
  /* the row stays (hidden) so that today's upload count cannot be reset by removing files */
  await req('PATCH','kb_files?id=eq.'+row.id,{status:'removed',facts_saved:0},'return=minimal');
  return out({ok:true,removed:true,name:row.name});
}
return out({ok:false,error:'Unknown action.'});
}catch(e){ return [{json:{ok:false,error:'Something went wrong: '+String((e&&e.message)||e).slice(0,160)}}]; }
